CREATE TABLE "PUBLIC"."LANGUAGE"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CODE" CHARACTER VARYING(10) NOT NULL,
    "NAME" CHARACTER VARYING(100) NOT NULL,
    "IS_DEFAULT" BOOLEAN DEFAULT FALSE NOT NULL,
    "IS_ENABLED" BOOLEAN DEFAULT TRUE NOT NULL
);;
ALTER TABLE "PUBLIC"."LANGUAGE" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_LANGUAGE_PK" PRIMARY KEY("ID");
ALTER TABLE "PUBLIC"."LANGUAGE" ADD CONSTRAINT "PUBLIC"."UQ_LANGUAGE_CODE" UNIQUE("CODE");

CREATE TABLE "PUBLIC"."REVEAL_TRANSLATION"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "REVEAL_ID" BIGINT NOT NULL,
    "LANGUAGE_ID" BIGINT NOT NULL,
    "DISPLAYED_DATE" CHARACTER VARYING,
    "DISPLAYED_TITLE" CHARACTER VARYING,
    "DISPLAYED_DESCRIPTION" CHARACTER VARYING,
    "SOURCE" CHARACTER VARYING(50),
    "CREATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "UPDATED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);;
ALTER TABLE "PUBLIC"."REVEAL_TRANSLATION" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_REVEAL_TRANSLATION_PK" PRIMARY KEY("ID");
ALTER TABLE "PUBLIC"."REVEAL_TRANSLATION" ADD CONSTRAINT "PUBLIC"."UQ_REVEAL_TRANSLATION_REVEAL_LANGUAGE" UNIQUE("REVEAL_ID", "LANGUAGE_ID");
ALTER TABLE "PUBLIC"."REVEAL_TRANSLATION" ADD CONSTRAINT "PUBLIC"."FK_REVEAL_TRANSLATION_REVEAL" FOREIGN KEY("REVEAL_ID") REFERENCES "PUBLIC"."REVEAL"("ID") ON DELETE CASCADE;
ALTER TABLE "PUBLIC"."REVEAL_TRANSLATION" ADD CONSTRAINT "PUBLIC"."FK_REVEAL_TRANSLATION_LANGUAGE" FOREIGN KEY("LANGUAGE_ID") REFERENCES "PUBLIC"."LANGUAGE"("ID");

CREATE INDEX "PUBLIC"."IDX_REVEAL_TRANSLATION_REVEAL_ID" ON "PUBLIC"."REVEAL_TRANSLATION"("REVEAL_ID");
CREATE INDEX "PUBLIC"."IDX_REVEAL_TRANSLATION_LANGUAGE_ID" ON "PUBLIC"."REVEAL_TRANSLATION"("LANGUAGE_ID");